import { drizzle } from 'drizzle-orm/postgres-js';
import { users } from './schema';

const db = drizzle({ client });

// Upsert: insert or update on email conflict
await db.insert(users)
  .values({ email: 'alice@example.com', name: 'Alice', updatedAt: new Date() })
  .onConflictDoUpdate({
    target: users.email,       // conflict target (unique column)
    set: {
      name: 'Alice Updated',   // what to update
      updatedAt: new Date(),
    },
  });

// Or ignore conflicts:
await db.insert(users)
  .values({ email: 'alice@example.com', name: 'Alice' })
  .onConflictDoNothing();

import { drizzle } from 'drizzle-orm/postgres-js';
import { users, posts } from './schema';
import { eq, inArray } from 'drizzle-orm';

const db = drizzle({ client });

// Build typed subquery
const publishedAuthors = db
  .select({ userId: posts.userId })
  .from(posts)
  .where(eq(posts.published, true));

// Use it as a subquery with inArray
const result = await db
  .select()
  .from(users)
  .where(inArray(users.id, publishedAuthors));

// Alternative: as() for aliased subqueries
const sq = db
  .select({ id: users.id, name: users.name })
  .from(users)
  .as('subq');

const outer = await db.select().from(sq).where(eq(sq.name, 'Alice'));

