import { drizzle } from 'drizzle-orm/postgres-js';
import { users, posts } from './schema';

const db = drizzle({ client });

// Drizzle transactions use a callback with the tx client
const result = await db.transaction(async (tx) => {
  // Use tx (not db) inside the transaction
  const [newUser] = await tx
    .insert(users)
    .values({ name: 'Alice', email: 'alice@example.com' })
    .returning();

  await tx
    .insert(posts)
    .values({ title: 'First Post', userId: newUser.id, published: false });

  return newUser;
});

// If any query throws, the entire transaction is rolled back automatically
